mapper.insert:
INSERT INTO group_link (
  link_url, group_name, origin, membership_state, sync_protocol_mask, created_at, updated_at
) VALUES (
  #{row.linkUrl}, #{row.groupName}, #{row.origin}, #{row.membershipState}, #{row.syncProtocolMask},
  #{row.createdAt}, #{row.updatedAt}
)
ON DUPLICATE KEY UPDATE
  deleted_at = NULL,
  group_name = COALESCE(NULLIF(TRIM(#{observedGroupName}), ''), group_name),
  membership_state = CASE WHEN membership_state = 3 THEN 3 ELSE 2 END,
  sync_protocol_mask = CASE
    WHEN sync_protocol_mask = 0 THEN #{row.syncProtocolMask}
    WHEN sync_protocol_mask = #{row.syncProtocolMask} THEN sync_protocol_mask
    ELSE 3
  END,
  updated_at = #{row.updatedAt}

mapper.select:
SELECT groupJid, groupLinkId, linkUrl FROM ( SELECT candidates.groupJid, candidates.groupLinkId, candidates.linkUrl, ROW_NUMBER() OVER ( PARTITION BY candidates.groupJid ORDER BY candidates.activeRank ASC, candidates.groupLinkId ASC ) AS rowNo FROM ( SELECT SUBSTRING(handle.link_url, CHAR_LENGTH('wa://group/') + 1) AS groupJid, handle.id AS groupLinkId, handle.link_url AS linkUrl, CASE WHEN handle.deleted_at IS NULL THEN 0 ELSE 1 END AS activeRank FROM group_link handle WHERE handle.tenant_id = #{tenantId} AND handle.link_url IN
CONCAT('wa://group/', #{groupJid})
UNION ALL SELECT current_group.group_jid AS groupJid, handle.id AS groupLinkId, handle.link_url AS linkUrl, CASE WHEN handle.deleted_at IS NULL THEN 0 ELSE 1 END AS activeRank FROM wa_group current_group INNER JOIN group_link handle ON handle.tenant_id = current_group.tenant_id AND handle.group_id = current_group.id WHERE current_group.tenant_id = #{tenantId} AND current_group.group_jid IN
#{groupJid}
) candidates ) ranked WHERE rowNo = 1 ORDER BY groupJid ASC

